package server

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"net"
	"time"

	"github.com/itzg/mc-router/mcproto"
)

// probeStatusTimeout bounds a single real Minecraft status-handshake probe
// attempt used to gate Docker auto-scale-up wake completion. Kept short so a
// not-yet-ready backend fails fast and the caller's own retry loop (see
// makeWakerFunc in docker.go) can keep polling within its overall deadline.
const probeStatusTimeout = 1500 * time.Millisecond

// probeMinecraftStatus performs a genuine, minimal Minecraft Java Edition
// status handshake (Handshake -> Status Request -> Status Response) against
// endpoint. Unlike a bare TCP dial, this proves the backend's network/game
// protocol handler is actually initialized and answering real Minecraft
// packets -- not just that some socket is listening.
//
// NXEON PATCH (2026-09-20): closes a reproduced live bug where mc-router's
// Docker auto-scale-up waker only waited for a raw TCP connect to succeed
// before declaring the backend "woken" and relaying the player's real
// connection to it. On itzg/minecraft-server, the TCP accept can happen
// slightly before the server's Netty pipeline is fully wired up to handle
// packets, so the player's actual first connection attempt right after a
// scale-up wake could get an immediate reset (0 bytes either direction).
// Gating wake-completion on a real protocol round-trip instead of a bare
// dial closes that race. See docker.go's makeWakerFunc for the call site.
func probeMinecraftStatus(endpoint string, host string, port uint64) error {
	conn, err := net.DialTimeout("tcp", endpoint, probeStatusTimeout)
	if err != nil {
		return err
	}
	defer func() { _ = conn.Close() }()

	_ = conn.SetDeadline(time.Now().Add(probeStatusTimeout))

	// --- Handshake packet (0x00): protocolVersion, serverAddress, serverPort, nextState=Status ---
	var hs bytes.Buffer
	if err := mcproto.WriteVarInt(&hs, 0); err != nil { // packetID 0x00 = Handshake
		return err
	}
	if err := mcproto.WriteVarInt(&hs, 0); err != nil { // protocol version: not checked for a status probe
		return err
	}
	if err := mcproto.WriteString(&hs, host); err != nil {
		return err
	}
	var portBuf [2]byte
	binary.BigEndian.PutUint16(portBuf[:], uint16(port))
	hs.Write(portBuf[:])
	if err := mcproto.WriteVarInt(&hs, int32(mcproto.StateStatus)); err != nil { // nextState = 1 (Status)
		return err
	}

	var framedHs bytes.Buffer
	if err := mcproto.WriteVarInt(&framedHs, int32(hs.Len())); err != nil {
		return err
	}
	framedHs.Write(hs.Bytes())

	// --- Status Request packet (0x00, empty payload), sent while in the Status state ---
	var sr bytes.Buffer
	if err := mcproto.WriteVarInt(&sr, 0); err != nil {
		return err
	}
	var framedSr bytes.Buffer
	if err := mcproto.WriteVarInt(&framedSr, int32(sr.Len())); err != nil {
		return err
	}
	framedSr.Write(sr.Bytes())

	if _, err := conn.Write(framedHs.Bytes()); err != nil {
		return fmt.Errorf("writing handshake: %w", err)
	}
	if _, err := conn.Write(framedSr.Bytes()); err != nil {
		return fmt.Errorf("writing status request: %w", err)
	}

	frame, err := mcproto.ReadFrame(conn, conn.RemoteAddr())
	if err != nil {
		return fmt.Errorf("reading status response frame: %w", err)
	}
	remainder := bytes.NewBuffer(frame.Payload)
	packetID, err := mcproto.ReadVarInt(remainder)
	if err != nil {
		return fmt.Errorf("reading status response packet id: %w", err)
	}
	if packetID != mcproto.PacketIdStatusResponse {
		return fmt.Errorf("unexpected packet id %d from status probe (expected Status Response)", packetID)
	}
	// A real Status Response carries a non-trivial JSON payload (version,
	// players, description, ...). Require some bytes back so a
	// truncated/garbage reply during a mid-handshake reset isn't mistaken
	// for a ready backend.
	if remainder.Len() < 2 {
		return fmt.Errorf("empty status response payload from probe")
	}
	return nil
}

