package server

import (
	"bufio"
	"net"
	"testing"
	"time"

	"github.com/itzg/mc-router/mcproto"
)

// TestProbeMinecraftStatus_Success spins up a fake Minecraft server that
// answers a real handshake+status-request with a status response, and
// verifies probeMinecraftStatus succeeds against it.
func TestProbeMinecraftStatus_Success(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	defer ln.Close()

	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		reader := bufio.NewReader(conn)

		// Read handshake
		pkt, err := mcproto.ReadPacket(reader, conn.RemoteAddr(), mcproto.StateHandshaking)
		if err != nil || pkt.PacketID != mcproto.PacketIdHandshake {
			return
		}
		// Read status request
		pkt2, err := mcproto.ReadPacket(reader, conn.RemoteAddr(), mcproto.StateStatus)
		if err != nil || pkt2.PacketID != mcproto.PacketIdStatusRequest {
			return
		}
		var status mcproto.StatusResponse
		status.Version.Name = "1.21.5"
		status.Version.Protocol = 770
		status.Players.Max = 20
		status.Players.Online = 0
		status.Description = map[string]interface{}{"text": "test"}
		_ = mcproto.WriteStatusFromStruct(conn, status)
	}()

	addr := ln.Addr().(*net.TCPAddr)
	err = probeMinecraftStatus(addr.String(), "127.0.0.1", uint64(addr.Port))
	if err != nil {
		t.Fatalf("expected probe success, got error: %v", err)
	}
}

// TestProbeMinecraftStatus_ResetDuringHandshake simulates exactly the bug
// being fixed: a listener that accepts the TCP connection (so a bare dial
// would succeed) but resets immediately without speaking the protocol --
// the probe must report this as NOT ready.
func TestProbeMinecraftStatus_ResetDuringHandshake(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	defer ln.Close()

	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		// Accept the TCP connection (like the container's port being
		// mapped) but immediately hard-close it without responding --
		// mirroring the real "0 bytes both directions" reset repro.
		if tcpConn, ok := conn.(*net.TCPConn); ok {
			_ = tcpConn.SetLinger(0) // force RST on close
		}
		_ = conn.Close()
	}()

	addr := ln.Addr().(*net.TCPAddr)
	err = probeMinecraftStatus(addr.String(), "127.0.0.1", uint64(addr.Port))
	if err == nil {
		t.Fatalf("expected probe to report not-ready on an immediate reset, got success")
	}
}

// TestProbeMinecraftStatus_NoListener confirms a straightforward dial
// failure (nothing listening yet) is reported as an error, same as before.
func TestProbeMinecraftStatus_NoListener(t *testing.T) {
	// Bind and immediately close to get a very likely-unused port with
	// nothing listening.
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	addr := ln.Addr().(*net.TCPAddr)
	ln.Close()

	err = probeMinecraftStatus(addr.String(), "127.0.0.1", uint64(addr.Port))
	if err == nil {
		t.Fatalf("expected error dialing a closed port, got success")
	}
}

