#!/usr/bin/env python3
"""Real Minecraft LOGIN-state handshake probe, used to test mc-router's
wake-from-sleep behavior without a full game client. Connects, sends a
Handshake (next_state=2/Login) + Login Start, then reports how many bytes
came back and how long it took. A 0-byte immediate close/reset here is
exactly the bug being tested for; real bytes back means the backend
actually processed the login."""
import socket
import struct
import sys
import time


def write_varint(v):
    out = bytearray()
    while True:
        b = v & 0x7F
        v >>= 7
        if v:
            b |= 0x80
        out.append(b)
        if not v:
            break
    return bytes(out)


def write_string(s):
    b = s.encode("utf8")
    return write_varint(len(b)) + b


def build_packet(packet_id, payload):
    body = write_varint(packet_id) + payload
    return write_varint(len(body)) + body


def main():
    host, port, server_address, player_name = sys.argv[1], int(sys.argv[2]), sys.argv[3], sys.argv[4]
    t0 = time.time()
    try:
        s = socket.create_connection((host, port), timeout=90)
    except Exception as e:
        print(f"CONNECT_FAIL after {time.time()-t0:.2f}s: {e}")
        return
    s.settimeout(90)

    hs_payload = (
        write_varint(770)
        + write_string(server_address)
        + struct.pack(">H", port)
        + write_varint(2)
    )
    ls_payload = write_string(player_name) + bytes(16)

    try:
        s.sendall(build_packet(0, hs_payload))
        s.sendall(build_packet(0, ls_payload))
    except Exception as e:
        print(f"SEND_FAIL after {time.time()-t0:.2f}s: {e}")
        s.close()
        return

    total = 0
    err = None
    try:
        while True:
            chunk = s.recv(65536)
            if not chunk:
                break
            total += len(chunk)
            # Stop once we've clearly received a real response (login
            # success / set-compression / disconnect are all well over a
            # few dozen bytes); avoids hanging waiting for a full play-state
            # stream we can't decode anyway.
            if total > 32:
                break
    except Exception as e:
        err = e

    elapsed = time.time() - t0
    if total == 0 and err is None:
        print(f"ZERO_BYTES_CLEAN_CLOSE after {elapsed:.2f}s (matches the bug: connection accepted then closed with nothing sent back)")
    elif total == 0 and err is not None:
        print(f"ZERO_BYTES_ERROR after {elapsed:.2f}s: {err} (matches the bug: reset before any data)")
    elif err is not None:
        print(f"GOT {total} BYTES then error after {elapsed:.2f}s: {err}")
    else:
        print(f"OK: received {total} bytes after {elapsed:.2f}s (real protocol response -- backend was actually ready)")
    s.close()


if __name__ == "__main__":
    main()

