import { db } from "../lib/db";
import { withServerSsh, exec, QUICK_TIMEOUT_MS, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
import type { SftpServer } from "../lib/sftp";

async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

async function run(conn: any, label: string, cmd: string, timeout = QUICK_TIMEOUT_MS) {
  const r = await exec(conn, cmd, timeout);
  console.log(`\n=== ${label} ===`);
  console.log(`$ ${cmd}`);
  console.log(`[exit ${r.code}]`);
  if (r.stdout.trim()) console.log(r.stdout.trim());
  if (r.stderr.trim()) console.log("STDERR:", r.stderr.trim());
  return r;
}

const TARGET = "mc-free-cmu8twhyx05tthl54xgszqceh"; // frostmc.play.nxeon.cloud, the exact original repro server, currently asleep, not a paying customer
const SERVER_ADDR = "frostmc.play.nxeon.cloud";

async function main() {
  const host = await freemcHost();
  await withServerSsh(host, async (conn) => {
    await run(conn, "ensure target asleep before test", `docker inspect -f '{{.State.Status}}' ${TARGET}`);
    await run(conn, "cleanup any stale baseline test router", "docker rm -f mc-router-baseline-test 2>/dev/null; echo ok");
    await run(conn, "start OLD-image test router on :25567", `docker run -d --name mc-router-baseline-test --network freemc -v /var/run/docker.sock:/var/run/docker.sock:ro -p 25567:25565 --user 0:0 itzg/mc-router:latest -in-docker -auto-scale-up -auto-scale-down -auto-scale-down-after=15m -auto-scale-asleep-motd "Server is asleep - connect to wake it up" -auto-scale-loading-motd "Starting your server..."`, SETUP_TIMEOUT_MS);
    await run(conn, "wait for router to init", "sleep 2; docker ps --filter name=mc-router-baseline-test");
    for (let i = 1; i <= 3; i++) {
      await run(conn, `attempt ${i} vs OLD image (port 25567)`, `python3 /root/mc_login_probe.py 127.0.0.1 25567 ${SERVER_ADDR} nxeontest${i}`, 100000);
      // Force back to sleep between attempts so each one exercises a fresh wake, mirroring the real bug's "asleep -> connect" trigger.
      await run(conn, `re-stop target after attempt ${i}`, `docker stop ${TARGET} 2>&1; docker inspect -f '{{.State.Status}}' ${TARGET}`, SETUP_TIMEOUT_MS);
    }
    await run(conn, "teardown baseline test router", "docker rm -f mc-router-baseline-test");
  });
}
main().then(() => process.exit(0)).catch((e) => { console.error("FAILED:", e); process.exit(1); });
